function [u] = deg2_potential(x, dc2, ds2, mu, re)
%DEG2_POTENTIAL  The degree-2 potential of a tide at x [m^2/s^2]: mu/|x| (Re/|x|)^2 sum Pbar(2, m) (dC2m cos m lam + dS2m sin m lam).
%   x: real[1][3] (passed a plain number)
%   dc2: real[1][3] (passed a plain number)
%   ds2: real[1][3] (passed a plain number)
%   mu: real[1] (passed a plain number)
%   re: real[1] (passed a plain number)
%   returns u: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    u = 0;
    xr = asils.models.gravity.onorm(x);
    phi = asils.pc.asin_((x(3) / xr));
    lam = atan2(x(2), x(1));
    p = asils.models.solidtides.norm_legendre5(sin(phi), 2);
    u = 0;
    for m = (0):((3) - 1)
        ml = (m * lam);
        u = (u + ((((mu / xr) * asils.pc.ipow((re / xr), 2)) * p(3, (m) + 1)) * ((dc2((m) + 1) * cos(ml)) + (ds2((m) + 1) * sin(ml)))));
    end
end
